/**
 * Fontes do certificado, embutidas como base64 -- o renderer bloqueia
 * toda requisição de rede (documentRendererService.js), então um
 * @import de CDN de fontes (como o template original
 * certificate-preview.html usava) simplesmente falharia
 * silenciosamente. Baixadas uma única vez em tempo de implementação
 * (Google Fonts, licença Open Font License) e embutidas aqui --
 * nenhuma rede é acessada em tempo de renderização.
 *
 * Great Vibes (peso 400) e UnifrakturCook (peso 700) são fontes
 * estáticas de peso único; Inter é uma fonte variável (um único
 * arquivo cobre os pesos 400-700, por isso um só @font-face
 * com font-weight: 400 700 em vez de 4 declarações repetidas).
 */

const GREAT_VIBES_BASE64 = "";
const INTER_VARIABLE_BASE64 = "";
const UNIFRAKTUR_COOK_BASE64 = "";

const FONT_FACES_CSS = `
  @font-face {
    font-family: 'Great Vibes';
    font-style: normal;
    font-weight: 400;
    src: url(data:font/woff2;base64,${GREAT_VIBES_BASE64}) format('woff2');
  }
  @font-face {
    font-family: 'Inter';
    font-style: normal;
    font-weight: 400 700;
    src: url(data:font/woff2;base64,${INTER_VARIABLE_BASE64}) format('woff2');
  }
  @font-face {
    font-family: 'UnifrakturCook';
    font-style: normal;
    font-weight: 700;
    src: url(data:font/woff2;base64,${UNIFRAKTUR_COOK_BASE64}) format('woff2');
  }
`;

module.exports = { FONT_FACES_CSS };
